import{_ as i,o as t,c as n,ah as a}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Schlacht der Gutachten: Wenn Statistik Korruption wegwäscht","description":"Wie eine neue WU-Studie versucht, den Inseraten-Skandal um Eva Dichand und Thomas Schmid neu zu definieren.","frontmatter":{"title":"Schlacht der Gutachten: Wenn Statistik Korruption wegwäscht","description":"Wie eine neue WU-Studie versucht, den Inseraten-Skandal um Eva Dichand und Thomas Schmid neu zu definieren.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-04-07-scientific-washing-dichand.md","filePath":"logbuch/2026-04-07-scientific-washing-dichand.md"}'),r={name:"logbuch/2026-04-07-scientific-washing-dichand.md"};function s(h,e,c,d,u,l){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="schlacht-der-gutachten-wenn-statistik-korruption-wegwascht" tabindex="-1">Schlacht der Gutachten: Wenn Statistik Korruption wegwäscht <a class="header-anchor" href="#schlacht-der-gutachten-wenn-statistik-korruption-wegwascht" aria-label="Permalink to &quot;Schlacht der Gutachten: Wenn Statistik Korruption wegwäscht&quot;">​</a></h1><p><strong>Wien, 7. April 2026</strong> – Während wir im Projekt die 500.000er-Marke im Viralitäts-Index durchbrechen, tobt draußen eine wissenschaftliche Abwehrschlacht. Die Verteidigung von Eva Dichand (<em>Heute</em>) hat heute eine Studie der WU Wien präsentiert, die belegen soll, dass es keine „wohlwollende Berichterstattung“ für Sebastian Kurz gab.</p><h2 id="das-„scientific-washing-der-macht" tabindex="-1">Das „Scientific Washing“ der Macht <a class="header-anchor" href="#das-„scientific-washing-der-macht" aria-label="Permalink to &quot;Das „Scientific Washing“ der Macht&quot;">​</a></h2><p>Es ist ein faszinierendes Phänomen: 250.000 Artikel wurden durch eine KI gejagt, um zu beweisen, dass <em>Heute</em> eigentlich neutral (oder gar SPÖ-freundlich) war. Damit soll das „Quid Pro Quo“ – also der Tausch von Inseratengeld gegen gute Stimmung – entkräftet werden.</p><p>Die Verteidigung um Michael Rami und Johann Pauer geht nun in die Offensive:</p><ul><li><strong>Der Kronzeuge im Kreuzfeuer:</strong> Thomas Schmid soll in einer „widersprüchlichen Einvernahme“ (ein juristisches Neuland) direkt konfrontiert werden.</li><li><strong>Die Lücke:</strong> Wenn die Statistik sagt „alles okay“, wie erklären wir dann die Chats, in denen Schmid die Inseratenvergabe als strategisches Tool feiert?</li></ul><h2 id="die-parallele-zum-horten-mysterium" tabindex="-1">Die Parallele zum Horten-Mysterium <a class="header-anchor" href="#die-parallele-zum-horten-mysterium" aria-label="Permalink to &quot;Die Parallele zum Horten-Mysterium&quot;">​</a></h2><p>In unserem Projekt untersuchen wir die „Horten-Logik“: Wer das Geld hat, definiert die Wahrheit. Heute wird diese Wahrheit nicht mehr nur durch einfache Inserate, sondern durch komplexe wissenschaftliche Gutachten untermauert.</p><p>Wir integrieren diese „Schlacht der Gutachten“ als neues Element in <strong>Teil 4 unseres Drehbuchs</strong>. Es geht um die Frage: Kann eine Statistik die moralische Realität von Chats überschreiben?</p><p><em>Der Index der Aufmerksamkeit steigt weiter. Die Wahrheit wird digital neu verhandelt.</em></p><hr><p>👈 <a href="/logbuch/">Zurück zum Logbuch</a> 🔮 <a href="/orakel.html">Das Orakel nach der Wahrheit befragen</a></p>',12)])])}const g=i(r,[["render",s]]);export{m as __pageData,g as default};
